<?php $this->assign('title','Apontamentos recebidos'); ?>
<div class="page-heading"><h1>Apontamentos recebidos</h1><?= $this->Html->link('Todas as atividades / O.S.',['controller'=>'Atividades','action'=>'index'],['class'=>'btn btn-outline-secondary']) ?></div>
<p>Somente apontamentos aguardando lançamento manual no TOTVS, por ordem de recebimento mais antigo. Nenhuma escrita automática no TOTVS.</p>
<section class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>O.S.</th><th>Serviço / equipamento</th><th>Setor</th><th>Apontamentos pendentes</th><th>Horas pendentes</th><th>Primeiro recebido</th><th>Ação</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><?= h($r['os_numero']) ?> / <?= h($r['os_filial']) ?></td><td><?= h($r['servico']) ?><br><?= h($r['bem']) ?></td><td><?= h($r['setor']??'Identificação pendente') ?></td><td><?= h($r['quantidade']) ?></td><td><?= number_format($r['minutos']/60,2,',','.') ?></td><td><?= h((new \DateTimeImmutable($r['recebido'],new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('America/Sao_Paulo'))->format('d/m/Y H:i')) ?></td><td><?= $this->Html->link('Ver apontamentos',['action'=>'view',$r['id']],['class'=>'btn btn-primary btn-sm']) ?></td></tr><?php endforeach; ?>
